export const SAVING_AND_GOALS_ACTIVITIES = [
{n:1,type:"mcq",micro:"Apa itu menabung",q:"Menabung pada dasarnya berarti...",options:["Menyisihkan sebagian uang sekarang untuk dipakai nanti, bukan menghabiskannya semua","Kehilangan uangmu selamanya karena uang yang sudah disimpan tidak akan pernah bisa dipakai lagi","Memberikan uang ke bank atau celengan tanpa pernah bisa mengambilnya kembali kapan pun kamu perlu"],answer:0,explain:"Menabung adalah menunda pemakaian sebagian uang. Uang itu tetap milikmu, hanya menunggu.",hint:"Uang yang ditabung hilang, atau menunggu untuk dipakai nanti?"},
{n:2,type:"mcq",micro:"Mengapa menabung",q:"Alasan utama menabung:",options:["Karena disuruh","Bisa membeli hal yang lebih besar nanti, & siap menghadapi kebutuhan mendadak tanpa berutang","Supaya terlihat kaya"],answer:1,explain:"Menabung membeli dua hal: kemampuan mencapai tujuan besar, & keamanan saat ada kejutan.",hint:"Apa yang kamu dapatkan dari punya uang yang disisihkan?"},
{n:3,type:"mcq",micro:"Menabung = menunda kesenangan",q:"Menabung Rp10.000 hari ini alih-alih membeli jajan berarti...",options:["Kehilangan Rp10.000","Tidak berdampak apa-apa","Menukar kesenangan kecil sekarang dengan sesuatu yang lebih berarti nanti"],answer:2,explain:"Setiap keputusan menabung adalah memilih 'nanti' daripada 'sekarang' untuk sebagian uang.",hint:"Apa yang kamu korbankan, & apa yang kamu dapatkan sebagai gantinya?"},
{n:4,type:"mcq",micro:"Tujuan tabungan",q:"'Tujuan tabungan' adalah...",options:["Hal spesifik yang kamu tabung uangnya (sepeda, kursus, hadiah, dana darurat)","Nama bank","Jumlah uang di dompet"],answer:0,explain:"Tujuan yang jelas membuat menabung terasa bermakna & memudahkan mengukur kemajuan.",hint:"Kamu menabung UNTUK apa?"},
{n:5,type:"mcq",micro:"Tujuan yang jelas",q:"Manakah tujuan tabungan yang paling jelas & bisa dipantau?",options:["Aku ingin menabung banyak uang supaya suatu hari nanti aku bisa membeli apa saja yang kuinginkan","Aku ingin Rp300.000 untuk sepatu bola dalam 3 bulan, yaitu Rp25.000/minggu","Aku ingin kaya raya suatu hari nanti, entah kapan dan entah untuk membeli barang apa saja"],answer:1,explain:"Tujuan yang baik menyebut jumlah, keperluan, tenggat, & langkah rutinnya — sehingga kemajuannya bisa diukur.",hint:"Mana yang bisa kamu cek 'sudah sampai mana' setiap minggu?"},
{n:6,type:"order",micro:"Menabung untuk tujuan",q:"Urutkan langkah menabung untuk sepeda seharga Rp600.000.",items:["Tetapkan tujuan yang jelas: sepeda Rp600.000","Tentukan berapa yang bisa kamu sisihkan tiap minggu, mis. Rp25.000","Hitung waktu: Rp600.000 ÷ Rp25.000 = 24 minggu","Simpan jumlah itu secara rutin & pantau perkembangannya"],answer:[0,1,2,3],explain:"Tujuan jelas → jumlah rutin → perkiraan waktu → menabung konsisten & memantau.",hint:"Kamu butuh target dulu sebelum bisa menghitung berapa lama."},
{n:7,type:"mcq",micro:"Bayar diri sendiri dulu",q:"Strategi 'bayar diri sendiri dulu' berarti...",options:["Membeli hadiah untuk diri sendiri lebih dulu begitu uang diterima, lalu tabungan diambil dari sisanya","Membayar utang paling akhir, setelah semua keinginan dan kesenanganmu bulan itu terpenuhi dulu","Menyisihkan tabungan begitu menerima uang, SEBELUM membelanjakan sisanya"],answer:2,explain:"Kalau menabung menunggu 'sisa', sering tidak ada sisa. Menyisihkan di awal membuat tabungan lebih pasti.",hint:"Kapan lebih mungkin ada uang untuk ditabung — di awal atau di akhir?"},
{n:8,type:"mcq",micro:"Dana darurat",q:"'Dana darurat' adalah tabungan yang...",options:["Disisihkan khusus untuk kejadian tak terduga (alat sekolah rusak, sakit, kehilangan)","Dipakai khusus untuk liburan bersama keluarga atau teman setiap akhir semester tiba","Harus dihabiskan setiap bulan supaya uangnya tidak menumpuk dan tidak sempat hilang dicuri"],answer:0,explain:"Dana darurat memberi rasa aman: saat ada pengeluaran mendadak, kamu tidak perlu berutang.",hint:"Untuk apa uang yang sengaja tidak disentuh kecuali keadaan mendesak?"},
{n:9,type:"mcq",micro:"Tempat menyimpan tabungan",q:"Untuk tabungan yang agak besar, tempat yang lebih aman:",options:["Diselipkan di antara halaman buku pelajaran yang setiap hari dibawa ke sekolah dan dipinjam teman","Rekening bank, atau celengan yang disimpan orang tua di tempat aman","Dimasukkan ke saku celana yang sering dicuci dan dibiarkan di keranjang pakaian kotor"],answer:1,explain:"Uang mudah hilang atau rusak jika disimpan sembarangan. Tempat aman melindungi tabunganmu.",hint:"Mana yang paling kecil kemungkinannya hilang atau rusak?"},
{n:10,type:"mcq",micro:"Menabung teratur vs sekali besar",q:"Menabung Rp10.000 setiap minggu selama setahun (52 minggu) menghasilkan...",options:["Rp52.000","Rp120.000","Rp520.000"],answer:2,explain:"Rp10.000 × 52 = Rp520.000. Kebiasaan kecil yang konsisten menghasilkan jumlah besar seiring waktu.",hint:"Kalikan jumlah mingguan dengan 52."},
{n:11,type:"tf",micro:"Menabung sedikit tetap berarti",q:"Benar atau Salah: Menabung jumlah kecil secara rutin (mis. Rp5.000/minggu) tetap menghasilkan jumlah berarti seiring waktu.",answer:true,explain:"Rp5.000/minggu = Rp260.000/tahun. Konsistensi lebih penting daripada besarnya tiap kali.",hint:"Berapa Rp5.000 setiap minggu selama setahun?"},
{n:12,type:"mcq",micro:"Tujuan jangka pendek vs panjang",q:"'Tabungan jangka pendek' (beberapa minggu/bulan) & 'jangka panjang' (bertahun) berbeda karena...",options:["Jangka pendek untuk hal dekat (hadiah, kegiatan); jangka panjang untuk hal besar (kursus, alat mahal, masa depan)","Tidak ada bedanya","Jangka panjang selalu lebih mudah"],answer:0,explain:"Memisahkan tabungan berdasarkan tenggat membantu tidak 'memakan' tabungan tujuan besar untuk keinginan kecil.",hint:"Apakah tabungan untuk hadiah minggu depan & untuk kursus tahun depan sama sifatnya?"},
{n:13,type:"mcq",micro:"Melacak kemajuan",q:"Mencatat berapa yang sudah terkumpul menuju tujuan berguna karena...",options:["Tidak ada gunanya","Membuat kemajuan terlihat, menjaga semangat, & menunjukkan berapa lagi yang dibutuhkan","Membuang waktu"],answer:1,explain:"'Sudah Rp250.000 dari Rp300.000, tinggal 2 minggu lagi' jauh lebih memotivasi daripada perasaan samar.",hint:"Bagaimana kamu tahu 'tinggal sedikit lagi'?"},
{n:14,type:"mcq",micro:"Godaan memakai tabungan",q:"Kamu hampir mencapai tujuan (kurang 2 minggu) lalu tergoda memakai tabungan untuk hal lain. Yang membantu bertahan:",options:["Pakai saja tabungan itu sekarang, sebab tujuan bisa dikejar lagi nanti kapan pun kamu sempat","Tabungan memang dibuat untuk dihabiskan kapan saja, jadi tidak perlu menahan diri sedikit pun","Ingat berapa lama & susah kamu menabung; keinginan sesaat jarang sepadan dengan mundurnya tujuan besar"],answer:2,explain:"Godaan sering muncul justru saat tujuan hampir tercapai. Mengingat usaha yang sudah keluar membantu.",hint:"Apa yang kamu korbankan kalau memakai tabungan tujuan sekarang?"},
{n:15,type:"tf",micro:"Celengan tidak bertambah sendiri",q:"Benar atau Salah: Uang di celengan tertutup akan bertambah dengan sendirinya seiring waktu, sama seperti tabungan di bank yang berbunga.",answer:false,explain:"Celengan tidak memberi imbalan apa pun; uang hanya bertambah kalau kamu memasukkan lebih banyak. Kelebihannya: uang tidak mudah terpakai. Kekurangannya: tidak tumbuh.",hint:"Apakah celengan memberi 'bunga'?"},
{n:16,type:"mcq",micro:"Bunga tabungan",q:"Saat kamu menyimpan uang di bank, bank kadang memberi 'bunga'. Bunga tabungan adalah...",options:["Tambahan uang dari bank sebagai imbalan karena kamu menyimpan uang di sana","Denda yang dikenakan bank karena kamu menabung terlalu sedikit pada bulan yang sedang berjalan","Biaya yang harus kamu bayar kepada bank setiap kali membuka rekening tabungan yang baru"],answer:0,explain:"Bank memakai simpananmu & memberi sedikit imbalan. Uangmu bisa tumbuh perlahan hanya dengan disimpan.",hint:"Bunga tabungan menambah atau mengurangi saldomu?"},
{n:17,type:"mcq",micro:"Menabung untuk membeli tunai",q:"Kelebihan menabung dulu lalu membeli tunai dibanding mencicil:",options:["Kamu membayar harga penuh barang ditambah bunga cicilan, sehingga total pengeluaranmu lebih besar","Kamu menghindari biaya bunga & tidak punya kewajiban cicilan tiap bulan","Barangnya jadi lebih mahal karena harus menunggu lama, dan toko pasti menaikkan harganya lagi"],answer:1,explain:"Membeli tunai dari tabungan berarti tidak ada bunga & tidak ada tekanan cicilan. Kekurangannya: harus menunggu.",hint:"Siapa yang membayar bunga saat kamu menabung lebih dulu?"},
{n:18,type:"mcq",micro:"Beberapa tujuan sekaligus",q:"Kamu punya tiga tujuan: dana darurat (belum ada), hadiah ibu bulan depan (tenggat dekat), sepatu bola (keinginan). Urutan menabung yang masuk akal:",options:["Sepatu bola dulu karena itu yang paling kamu inginkan, sedangkan dana darurat dan hadiah bisa menunggu","Abaikan semua tujuan itu dan tabung nanti saja kalau uang sakumu sudah jauh lebih banyak","Mulai dana darurat kecil DAN hadiah ibu (tenggat dekat) lebih dulu; sepatu bola setelahnya"],answer:2,explain:"Prioritas mempertimbangkan urgensi (tenggat), keamanan (darurat), lalu keinginan. Beberapa tujuan bisa jalan bersamaan dengan porsi berbeda.",hint:"Mana yang punya tenggat, & mana yang melindungimu dari masalah?"},
{n:19,type:"mcq",micro:"Menabung sebagai kebebasan",q:"Selain untuk membeli sesuatu, memiliki tabungan memberi...",options:["Kebebasan & ketenangan: bisa menghadapi kejadian tak terduga & menolak pilihan buruk (mis. pinjaman berbunga tinggi)","Beban pikiran yang lebih berat, karena kamu harus terus menjaga dan mengkhawatirkan tabunganmu","Kewajiban untuk membelanjakannya dengan cepat, supaya uang tidak lama menganggur di tabungan"],answer:0,explain:"Tabungan adalah penyangga. Orang dengan tabungan punya lebih banyak pilihan & lebih sedikit tekanan saat masalah datang.",hint:"Siapa yang lebih tenang saat sepatu tiba-tiba jebol: yang punya tabungan atau yang tidak?"},
{n:20,type:"open",micro:"Menetapkan tujuan tabungan",q:"Tetapkan satu tujuan tabungan pribadi. Tuliskan: (1) apa tepatnya & berapa harganya, (2) tenggat yang realistis, (3) berapa yang perlu kamu sisihkan tiap minggu, (4) dari mana uangnya (mengurangi apa), (5) di mana kamu menyimpannya & bagaimana melacak kemajuannya.",explain:"Jawaban baik menyebut tujuan spesifik + harga, tenggat realistis, jumlah mingguan hasil pembagian, sumber uang yang konkret (mengurangi keinginan tertentu), tempat penyimpanan aman, & cara melacak.",hint:"Tujuan tanpa 'berapa per minggu' & 'dari mana uangnya' hanya harapan.",sample:"Contoh: (1) Sepatu lari yang layak, Rp280.000. (2) Tenggat: 10 minggu (sebelum lomba sekolah). (3) Rp280.000 ÷ 10 = Rp28.000/minggu. (4) Uangnya dari mengurangi jajan minuman kemasan (Rp15.000 → Rp5.000/minggu, bawa minum sendiri) & top up gim (Rp15.000 → Rp2.000/minggu) = hemat Rp23.000; sisanya Rp5.000 dari uang saku. (5) Disimpan di amplop khusus 'sepatu' yang dipegang ibu, & aku catat di aplikasi catatan ponsel setiap setoran: minggu ke-, jumlah, total. Kalau ada uang lebih (hadiah), kupercepat."},
{n:21,type:"classify",micro:"Jenis tujuan tabungan",q:"Kelompokkan tiap tujuan sebagai 'Dana darurat', 'Jangka pendek', atau 'Jangka panjang'.",items:["Menyimpan uang untuk kalau tas/sepatu tiba-tiba rusak","Menabung untuk kado ulang tahun teman bulan depan","Menabung untuk kursus musik tahun depan"],groups:["Dana darurat","Jangka pendek","Jangka panjang"],answer:{"Dana darurat":["Menyimpan uang untuk kalau tas/sepatu tiba-tiba rusak"],"Jangka pendek":["Menabung untuk kado ulang tahun teman bulan depan"],"Jangka panjang":["Menabung untuk kursus musik tahun depan"]},explain:"Darurat = untuk kejutan; jangka pendek = tenggat dekat & spesifik; jangka panjang = tujuan besar berbulan/bertahun.",hint:"Apakah ini untuk kejutan, hal dekat, atau hal besar yang jauh?"},
{n:22,type:"mcq",micro:"Memisahkan tabungan",q:"Menyimpan uang untuk tujuan berbeda di 'wadah' terpisah (amplop, sub-rekening) berguna karena...",options:["Uang jadi lebih sedikit karena setiap wadah menyimpan sebagian dan sisanya hilang saat dipindahkan","Kamu tidak sengaja memakai tabungan tujuan besar untuk keinginan kecil, & kemajuan tiap tujuan terlihat jelas","Membuat menabung menjadi lebih rumit dan merepotkan tanpa memberi manfaat apa pun bagimu"],answer:1,explain:"Uang yang tercampur dalam satu wadah mudah 'bocor'. Memisahkannya menjaga tiap tujuan aman.",hint:"Apa yang terjadi kalau uang darurat & uang jajan ada di dompet yang sama?"},
{n:23,type:"mcq",micro:"Hambatan menabung: lupa",q:"Kalau kamu sering lupa menyisihkan tabungan, cara mengatasinya:",options:["Berharap ingat","Menyerah menabung","Jadikan otomatis atau rutin: setiap Senin pagi langsung pisahkan, atau minta bank/orang tua memindahkannya otomatis"],answer:2,explain:"Menabung yang bergantung pada 'ingat & niat' setiap kali sering gagal. Menjadikannya kebiasaan tetap atau otomatis jauh lebih andal.",hint:"Bagaimana membuat menabung terjadi tanpa harus memutuskannya setiap kali?"},
{n:24,type:"mcq",micro:"Hambatan menabung: godaan",q:"Kalau uang tabungan yang mudah diakses selalu tergoda kamu pakai, solusinya:",options:["Simpan di tempat yang sedikit 'sulit' dijangkau (dipegang orang tua, rekening tanpa kartu) sehingga butuh usaha untuk mengambilnya","Simpan di dompet yang selalu dibawa ke mana-mana agar mudah dipakai kapan pun kamu butuh jajan","Tidak menabung sama sekali supaya tidak ada uang yang bisa menggodamu untuk dibelanjakan"],answer:0,explain:"'Gesekan' kecil (harus minta, harus ke bank) memberi jeda untuk berpikir sebelum memakai tabungan.",hint:"Apa yang membuatmu berpikir dua kali sebelum mengambil dari tabungan?"},
{n:25,type:"mcq",micro:"Tujuan yang terlalu besar",q:"Tujuan Rp5.000.000 dengan tabungan Rp20.000/minggu butuh 250 minggu (~5 tahun). Kalau ini terasa melumpuhkan:",options:["Berutang untuk mendapatkannya sekarang","Pecah menjadi tonggak (mis. Rp1.000.000 pertama), rayakan tiap tonggak, & cari cara menambah pemasukan","Menyerah"],answer:1,explain:"Tujuan sangat besar lebih mudah dijalani lewat tonggak antara yang terasa tercapai.",hint:"Bagaimana orang mendaki gunung yang sangat tinggi?"},
{n:26,type:"mcq",micro:"Menabung dari uang tak terduga",q:"Kamu dapat uang hadiah Rp100.000 yang tidak direncanakan. Kebiasaan yang membantu tujuan:",options:["Habiskan semuanya sekaligus karena 'uang bonus' memang sebaiknya dinikmati tanpa perlu dipikirkan","Simpan begitu saja di dompet dan lupakan, lalu pakai sedikit-sedikit sampai tidak tersisa lagi","Sisihkan sebagian langsung ke tabungan tujuan sebelum menghabiskannya — 'uang kejutan' adalah kesempatan mempercepat"],answer:2,explain:"Uang tak terduga sering langsung habis kalau tidak ada rencana. Menyisihkan sebagian mempercepat tujuan tanpa terasa berkorban.",hint:"Apa yang biasanya terjadi pada 'uang bonus' yang tidak dialokasikan?"},
{n:27,type:"tf",micro:"Tujuan bisa disesuaikan",q:"Benar atau Salah: Begitu sebuah tujuan tabungan ditetapkan, ia harus dipegang persis seperti semula walaupun harga naik, kebutuhan mendesak muncul, atau minatmu berubah.",answer:false,explain:"Tujuan adalah alat, bukan janji kaku. Kalau keadaan berubah, boleh menyesuaikan jumlah, tenggat, atau tujuannya sendiri — itu lebih baik daripada menyerah atau memaksakan yang sudah tidak relevan.",hint:"Apakah tujuan yang dibuat 6 bulan lalu harus dipegang mati-matian meski keadaan berubah?"},
{n:28,type:"mcq",micro:"Menabung & pemasukan tidak tetap",q:"Kalau uang sakumu tidak tetap tiap minggu, cara menabung yang cocok:",options:["Tetapkan persentase (mis. 20% dari berapa pun yang diterima) daripada jumlah tetap","Hanya menabung di minggu-minggu ketika uang sakumu sedang banyak, dan berhenti total saat sedang sedikit","Tidak bisa menabung sama sekali, karena menabung hanya mungkin dilakukan bila uang saku selalu sama"],answer:0,explain:"Persentase menyesuaikan dengan pemasukan yang naik-turun & tetap membangun kebiasaan.",hint:"Bagaimana menabung konsisten kalau jumlah yang masuk berubah-ubah?"},
{n:29,type:"mcq",micro:"Tabungan vs kebutuhan mendesak",q:"Kamu sedang menabung untuk sepeda, lalu buku pelajaran wajib harus dibeli & uang tidak cukup. Sikap yang tepat:",options:["Batalkan seluruh tujuan membeli sepeda selamanya, karena rencana pertama yang terganggu pasti gagal","Kebutuhan mendesak & penting boleh didahulukan; sesuaikan tenggat sepeda, lalu lanjut menabung","Abaikan buku pelajaran demi sepeda, sebab buku bisa dipinjam atau dibeli oleh orang tua nanti"],answer:1,explain:"Kebutuhan penting mengalahkan tujuan keinginan. Menyesuaikan tenggat bukan kegagalan.",hint:"Mana yang lebih mendesak: buku wajib untuk sekolah, atau sepeda?"},
{n:30,type:"order",micro:"Membangun kebiasaan menabung",q:"Urutkan langkah membangun kebiasaan menabung yang bertahan.",items:["Tetapkan tujuan & jumlah/persentase yang realistis (jangan terlalu besar sampai menyiksa)","Pilih waktu tetap & tempat aman untuk menyisihkannya","Lakukan segera setiap kali menerima uang (bayar diri sendiri dulu)","Lacak kemajuan & rayakan tonggak; sesuaikan bila perlu"],answer:[0,1,2,3],explain:"Target realistis → waktu & tempat tetap → sisihkan lebih dulu → lacak & sesuaikan.",hint:"Kebiasaan butuh pemicu yang tetap & jumlah yang tidak menyiksa."},
{n:31,type:"mcq",micro:"Menabung terlalu ketat",q:"Menabung dengan porsi yang sangat besar sampai tidak ada uang untuk kesenangan sama sekali...",options:["Selalu merupakan strategi terbaik, karena semakin banyak yang disisihkan, semakin cepat tujuan tercapai","Membuat tujuan tercapai dengan pasti, sebab orang yang menabung ketat tidak pernah merasa lelah","Sering tidak bertahan lama — orang menyerah karena terasa menyiksa; porsi yang seimbang lebih berkelanjutan"],answer:2,explain:"Menabung yang berkelanjutan menyisakan sedikit ruang untuk menikmati. Terlalu ekstrem sering berujung berhenti total.",hint:"Apa yang terjadi pada rencana diet yang melarang semua makanan enak?"},
{n:32,type:"mcq",micro:"Motivasi visual",q:"Menempel gambar tujuan (sepeda, alat) atau membuat 'termometer tabungan' yang diisi berguna karena...",options:["Mengingatkan mengapa kamu menabung & membuat kemajuan terasa nyata & memuaskan","Tidak berpengaruh","Hanya untuk anak kecil"],answer:0,explain:"Pengingat visual menjaga tujuan tetap terlihat & membuat menyisihkan uang terasa seperti kemajuan, bukan kehilangan.",hint:"Apa yang membuat menabung terasa seperti 'maju' bukan 'kehilangan'?"},
{n:33,type:"tf",micro:"Menabung lebih dulu, belanja sisanya",q:"Benar atau Salah: Strategi 'belanja dulu, tabung kalau ada sisa' cenderung lebih berhasil daripada 'sisihkan tabungan lebih dulu, baru belanjakan sisanya'.",answer:false,explain:"Sebaliknya. Kalau menabung menunggu 'sisa', sering tidak ada sisa. Menyisihkan di awal (bayar diri sendiri dulu) membuat tabungan lebih pasti.",hint:"Kapan kemungkinan besar masih ada uang untuk ditabung?"},
{n:34,type:"mcq",micro:"Tujuan bersama",q:"Kamu & saudara ingin barang mahal yang sama. Pendekatan yang bisa dipertimbangkan:",options:["Meminta orang tua membelikan dua barang yang sama supaya kalian tidak perlu menabung maupun berbagi","Menabung bersama & berbagi pemakaian, atau masing-masing menabung sebagian — mengubah tujuan mahal jadi lebih terjangkau","Bertengkar sampai salah satu dari kalian menyerah, lalu yang menang boleh memakai barangnya sendiri"],answer:1,explain:"Berbagi biaya & pemakaian bisa membuat tujuan yang di luar jangkauan satu orang menjadi mungkin.",hint:"Apakah tujuan mahal harus selalu ditanggung satu orang?"},
{n:35,type:"mcq",micro:"Menabung untuk memberi",q:"Menyisihkan sebagian tabungan untuk hadiah atau membantu orang lain...",options:["Selalu pemborosan","Tidak dianggap menabung","Adalah tujuan tabungan yang sah — banyak orang menyertakan 'berbagi' dalam rencana keuangannya"],answer:2,explain:"Menabung untuk memberi (kado keluarga, sumbangan, membantu teman) adalah tujuan yang bermakna bagi banyak orang.",hint:"Apakah menabung hanya untuk membeli barang untuk diri sendiri?"},
{n:36,type:"mcq",micro:"Ketika menabung terasa lambat",q:"Di tengah menabung untuk tujuan besar, kemajuan terasa lambat & kamu ingin menyerah. Yang membantu:",options:["Lihat total yang sudah terkumpul (bukan yang tersisa), pecah jadi tonggak kecil, & ingat mengapa tujuan ini penting bagimu","Menyerah dan menghabiskan uang yang sudah terkumpul untuk hal lain supaya tidak merasa sia-sia lagi","Berutang kepada teman agar tujuan itu bisa dicapai dengan cepat, lalu dibayar kembali belakangan"],answer:0,explain:"Fokus pada kemajuan yang sudah dibuat & tonggak kecil menjaga semangat saat tujuan besar terasa jauh.",hint:"Mana yang lebih memotivasi: 'baru Rp200.000 dari Rp1.000.000' atau 'sudah Rp200.000, tonggak pertama tercapai'?"},
{n:37,type:"tf",micro:"Menabung membangun kebiasaan seumur hidup",q:"Benar atau Salah: Kebiasaan menabung yang dibentuk sejak muda tidak berpengaruh pada kehidupan dewasa; setiap orang harus membangunnya lagi dari nol setelah mulai bekerja.",answer:false,explain:"Menabung adalah otot yang dilatih. Kebiasaan menyisihkan yang dibentuk sejak muda cenderung terbawa & membantu sepanjang hidup, apa pun tingkat penghasilan nanti.",hint:"Apakah kebiasaan baik yang dibentuk sejak dini cenderung bertahan?"},
{n:38,type:"mcq",micro:"Tujuan yang berubah nilai",q:"Kamu menabung untuk mainan tertentu, lalu setelah 2 bulan tidak lagi menginginkannya. Pilihan yang bijak:",options:["Simpan uang itu begitu saja tanpa tujuan dan lupakan, siapa tahu nanti ada kebutuhan yang datang","Alihkan tabungan itu ke tujuan lain yang masih berarti (dana darurat, tujuan baru) — jangan langsung habiskan karena 'sudah tidak ada tujuan'","Habiskan semuanya untuk keinginan acak yang kebetulan terlihat menarik hari ini juga di toko"],answer:1,explain:"Ketika sebuah tujuan tidak lagi relevan, alihkan uangnya ke tujuan bermakna lain — bukan alasan untuk boros.",hint:"Apakah 'tujuan lama hilang' berarti 'boleh dihabiskan sembarangan'?"},
{n:39,type:"mcq",micro:"Menabung & tekanan sosial",q:"Teman-teman mengajak patungan untuk sesuatu yang tidak kamu minati, & uangmu sudah dialokasikan untuk tujuan tabungan. Respons:",options:["Ikut patungan dan mundurkan tujuan tabunganmu, karena menjaga pertemanan lebih penting dari rencana","Pinjam uang dari kakak atau teman lain supaya tetap bisa ikut tanpa menyentuh tabunganmu sama sekali","Menolak dengan sopan & menjelaskan uangmu sudah punya rencana; tawarkan cara ikut yang gratis"],answer:2,explain:"Melindungi tujuan tabungan kadang berarti mengatakan 'tidak' pada tekanan sosial. Teman yang baik menghormati itu.",hint:"Apakah tujuanmu layak dikorbankan untuk hal yang tidak kamu minati?"},
{n:40,type:"open",micro:"Merancang sistem menabung",q:"Rancang 'sistem menabung' pribadi untuk 3 bulan ke depan. Sertakan: (1) 2–3 tujuan (satu di antaranya dana darurat), (2) jumlah/persentase untuk tiap tujuan tiap minggu, (3) di mana tiap tujuan disimpan (wadah terpisah), (4) kapan & bagaimana kamu menyisihkannya (pemicu tetap), (5) cara melacak kemajuan, (6) apa yang kamu lakukan dengan uang tak terduga.",explain:"Sistem baik: tujuan spesifik (termasuk darurat), alokasi mingguan yang muat pemasukan, wadah terpisah, pemicu tetap (bayar diri sendiri dulu), pelacakan, & aturan untuk uang kejutan.",hint:"Kunci: wadah terpisah + pemicu tetap + menyisihkan SEBELUM belanja.",sample:"Contoh: (1) Tujuan: (a) dana darurat kecil target Rp150.000; (b) sepatu lari Rp280.000; (c) kado ibu Rp80.000 bulan ke-2. (2) Dari uang saku Rp60.000/minggu: dana darurat Rp10.000/minggu sampai Rp150.000 lalu berhenti; sepatu Rp15.000/minggu; kado ibu Rp10.000/minggu selama 8 minggu. (3) Tiga amplop terpisah dipegang ibu, diberi label; atau tiga catatan di aplikasi. (4) Setiap Senin pagi sepulang menerima uang saku, langsung pisahkan ketiganya SEBELUM jajan apa pun. (5) Catat di ponsel: tanggal, tujuan, jumlah, total baru. Setiap akhir bulan cek kemajuan vs target. (6) Uang tak terduga (hadiah, bantu paman): 50% ke tujuan yang paling dekat tenggatnya, 50% boleh dinikmati."},
{n:41,type:"mcq",micro:"Tujuan SMART",q:"Tujuan tabungan yang 'SMART' bersifat Spesifik, Terukur, dapat Dicapai, Relevan, & Terikat waktu. Manakah yang paling SMART?",options:["Menabung Rp450.000 untuk kamera bekas dalam 5 bulan dengan menyisihkan Rp22.500/minggu","Menabung untuk masa depan yang cerah, entah untuk apa, dan dilakukan kapan pun ada uang tersisa","Menabung banyak secepatnya sebelum uang sakumu habis, tanpa menentukan jumlah dan batas waktunya"],answer:0,explain:"Tujuan SMART menyebut jumlah, keperluan, tenggat, & langkah — sehingga bisa dipantau & realistis.",hint:"Mana yang bisa kamu cek kemajuannya setiap minggu?"},
{n:42,type:"mcq",micro:"Menghitung durasi tujuan",q:"Kamu ingin mengumpulkan Rp450.000 untuk kursus. Kamu bisa menabung Rp30.000/minggu & sudah punya Rp90.000. Berapa minggu lagi yang dibutuhkan?",options:["15 minggu","12 minggu","18 minggu"],answer:1,explain:"Sisa = Rp450.000 − Rp90.000 = Rp360.000. Rp360.000 ÷ Rp30.000 = 12 minggu.",hint:"Kurangi tabungan yang sudah ada dulu, lalu bagi dengan tabungan per minggu."},
{n:43,type:"mcq",micro:"Bunga majemuk (gagasan)",q:"Kamu menabung Rp100.000 di rekening berbunga 10%/tahun, & bunganya ikut ditabung. Setelah 2 tahun (bunga majemuk), saldonya sekitar...",options:["Rp110.000","Rp120.000","Rp121.000"],answer:2,explain:"Tahun 1: Rp100.000 → Rp110.000. Tahun 2: bunga 10% dari Rp110.000 = Rp11.000 → Rp121.000. Bunga menghasilkan bunga lagi.",hint:"Tahun kedua, bunga dihitung dari saldo baru, bukan dari Rp100.000."},
{n:44,type:"mcq",micro:"Mengapa mulai menabung lebih awal",q:"Karena bunga majemuk, mulai menabung lebih awal (meski jumlah kecil) berguna karena...",options:["Uang punya lebih banyak waktu untuk tumbuh; menabung sedikit sejak dini bisa mengalahkan menabung lebih banyak tapi terlambat","Tidak ada bedanya kapan mulai menabung, karena uang yang dikumpulkan akan sama saja pada akhirnya, baik dini maupun terlambat","Terlambat justru selalu lebih baik, sebab semakin singkat waktu menabung, semakin besar bunga yang diterima nantinya"],answer:0,explain:"Waktu adalah bahan bakar bunga majemuk. Setiap tahun lebih awal memberi 'pertumbuhan atas pertumbuhan' yang lebih lama.",hint:"Bola salju yang menggelinding lebih lama menjadi lebih besar — apa analoginya untuk menabung?"},
{n:45,type:"mcq",micro:"Inflasi & tabungan tunai",q:"Uang jajan Rp5.000 lima tahun lalu bisa membeli lebih banyak daripada Rp5.000 sekarang. Kecenderungan harga naik ini disebut inflasi. Implikasinya untuk tabungan:",options:["Menyimpan uang tunai selamanya di rumah adalah cara terbaik, karena nilainya pasti tidak pernah berubah sampai kapan pun","Uang tunai yang disimpan bertahun-tahun tanpa tumbuh kehilangan daya beli; tabungan jangka panjang sebaiknya di tempat yang setidaknya mengimbangi inflasi","Inflasi tidak memengaruhi tabungan sama sekali, karena yang berubah hanya harga barang, bukan nilai uang yang disimpan"],answer:1,explain:"Untuk tujuan jangka sangat panjang, uang tunai yang didiamkan 'menyusut' dibanding harga barang yang naik.",hint:"Kalau harga naik tapi uangmu tetap, apa yang terjadi pada apa yang bisa kamu beli?"},
{n:46,type:"mcq",micro:"Tabungan untuk berbagai jangka waktu",q:"Untuk dana darurat & tujuan dekat (< 1 tahun), tempat yang tepat:",options:["Tempat berisiko tinggi agar tumbuh cepat","Di dompet","Yang aman & mudah diambil saat dibutuhkan (rekening tabungan) — bukan tempat yang nilainya bisa turun sewaktu-waktu"],answer:2,explain:"Uang yang mungkin kamu butuhkan segera harus aman & likuid, bukan ditaruh di tempat yang bisa merugi saat kamu perlu.",hint:"Apa yang kamu butuhkan dari uang darurat: pertumbuhan tinggi atau tersedia kapan pun & utuh?"},
{n:47,type:"order",micro:"Menyusun rencana tabungan tujuan besar",q:"Urutkan langkah merencanakan tabungan untuk tujuan besar (mis. laptop Rp2.400.000).",items:["Pastikan kebutuhan bulanan & dana darurat kecil sudah aman","Tetapkan jumlah tabungan berkala (mingguan/bulanan) yang realistis","Hitung durasi & tonggak (mis. tiap Rp600.000)","Tabung konsisten, lacak, rayakan tonggak, & sesuaikan bila perlu"],answer:[0,1,2,3],explain:"Amankan kebutuhan & darurat → tetapkan jumlah berkala → hitung durasi & tonggak → jalankan & pantau.",hint:"Tujuan besar didanai lewat tabungan berkala + tonggak, bukan lompatan."},
{n:48,type:"mcq",micro:"Tujuan realistis",q:"Kamu ingin Rp2.400.000 dalam 3 bulan tapi hanya bisa menabung Rp200.000/bulan. Ini menunjukkan:",options:["Tenggat tidak realistis dengan tabungan saat ini; sesuaikan tenggat (jadi ~12 bulan), tambah pemasukan, atau pilih target lebih murah","Tetap paksakan target tiga bulan itu dan berutang kepada orang lain untuk menutup selisihnya, supaya tujuannya tercapai tepat waktu","Menyerah pada semua tujuan tabungan, karena jika satu target tidak masuk akal berarti menabung tidak akan pernah berhasil"],answer:0,explain:"Kalau angka tidak cocok, ubah salah satu variabel (tenggat, jumlah tabungan, atau target) — jangan berutang untuk menutup selisih keinginan.",hint:"Rp200.000 × 3 = Rp600.000. Apa yang perlu diubah agar rencananya masuk akal?"},
{n:49,type:"mcq",micro:"Menabung otomatis",q:"'Menabung otomatis' (bank memindahkan sejumlah tetap ke tabungan tiap kali uang masuk) membantu karena...",options:["Tidak berpengaruh","Menghilangkan kebutuhan untuk 'memutuskan menabung' setiap kali — ia terjadi sebelum kamu sempat membelanjakannya","Membuat kamu kehilangan kendali"],answer:1,explain:"Otomatisasi memanfaatkan 'bayar diri sendiri dulu' tanpa mengandalkan kemauan setiap kali.",hint:"Apa yang lebih andal: menabung yang butuh keputusan tiap kali, atau yang terjadi sendiri?"},
{n:50,type:"mcq",micro:"Menabung vs melunasi utang",q:"Kalau kamu punya utang berbunga tinggi & juga ingin menabung, prioritas yang umum:",options:["Abaikan utangnya dan menabung sebanyak mungkin lebih dulu, karena bunga utang tidak akan pernah menumpuk atau bertambah besar","Bayar utang itu paling akhir, setelah semua tujuan tabungan dan keinginan terpenuhi, sebab utang tidak perlu terburu-buru dilunasi","Sisihkan dana darurat kecil dulu, lalu fokuskan sebagian besar untuk melunasi utang berbunga tinggi (bunganya 'memakan' lebih cepat dari yang bisa ditumbuhkan tabungan)"],answer:2,explain:"Bunga utang tinggi biasanya lebih besar dari imbalan tabungan, jadi melunasinya adalah 'pengembalian' yang bagus — dengan tetap menyisakan penyangga darurat.",hint:"Kalau utang membebani bunga 20% & tabungan tumbuh 3%, mana yang lebih mendesak?"},
{n:51,type:"open",micro:"Menghitung & merencanakan tujuan",q:"Kamu ingin membeli tablet untuk belajar seharga Rp2.400.000. Uang sakumu Rp80.000/minggu; kamu juga bisa dapat Rp100.000/bulan dari membantu usaha orang tua. Buat rencana: berapa disisihkan tiap minggu/bulan, berapa lama sampai tercapai, apa yang dikorbankan, & satu cara mempercepat.",explain:"Rencana baik menghitung total tabungan bulanan, membagi harga untuk mendapat durasi, menyatakan biaya peluang (jajan & waktu), & memberi cara konkret mempercepat (tambah pemasukan atau turunkan target).",hint:"Total tabungan bulanan → bagi harga → durasi → sebut yang dikorbankan → satu cara mempercepat.",sample:"Sisihkan Rp40.000/minggu dari uang saku (= Rp160.000/bulan) + Rp100.000/bulan dari membantu usaha = Rp260.000/bulan. Rp2.400.000 ÷ Rp260.000 ≈ 9,2 bulan → sekitar 10 bulan. Yang dikorbankan: separuh jajan mingguan & sebagian waktu luang untuk membantu usaha. Cara mempercepat: cari pekerjaan kecil tambahan (mencuci motor tetangga akhir pekan) untuk menambah ~Rp60.000/bulan → total ~Rp320.000/bulan → tercapai dalam ~7,5 bulan; atau pilih tablet lebih murah Rp1.800.000 → ~7 bulan."},
{n:52,type:"mcq",micro:"Menabung & pajak/biaya (gagasan)",q:"Beberapa rekening tabungan memiliki biaya administrasi bulanan. Untuk tabungan kecil, ini penting karena...",options:["Biaya bisa 'memakan' tabungan kecil lebih cepat dari bunga yang diterima; pilih rekening tanpa/berbiaya rendah, atau celengan untuk jumlah kecil","Biaya administrasi selalu boleh diabaikan, karena jumlahnya pasti kecil dan tidak akan terasa pada tabungan berapa pun besarnya","Semua rekening tabungan pasti gratis tanpa biaya apa pun, sehingga tidak perlu membaca aturan bank sebelum membukanya"],answer:0,explain:"Untuk saldo kecil, biaya administrasi bisa membuat tabungan malah berkurang. Bandingkan biaya vs manfaat.",hint:"Kalau biaya Rp10.000/bulan & bunga hanya Rp2.000/bulan, apa yang terjadi pada saldomu?"},
{n:53,type:"tf",micro:"Tujuan yang tertulis lebih mungkin tercapai",q:"Benar atau Salah: Menuliskan tujuan tabungan (jumlah, tenggat, langkah) & melacaknya membuatnya lebih mungkin tercapai daripada hanya menyimpannya di kepala.",answer:true,explain:"Tujuan tertulis & terpantau memberi kejelasan, akuntabilitas, & rasa kemajuan yang menjaga kamu di jalur.",hint:"Apa yang lebih mudah dilupakan atau digeser: rencana di kertas atau di pikiran?"},
{n:54,type:"mcq",micro:"Menabung untuk peluang, bukan hanya barang",q:"Tujuan tabungan bisa juga berupa...",options:["Hanya untuk keadaan darurat saja, sehingga tidak boleh dipakai untuk kursus, hobi, ataupun modal usaha yang kamu impikan","Kesempatan (kursus, alat untuk hobi/usaha, biaya lomba, modal usaha kecil) yang membuka pintu di masa depan","Hanya barang yang bisa dimiliki dan dipegang, karena pengalaman dan kesempatan tidak termasuk tujuan menabung yang sah"],answer:1,explain:"Menabung untuk pengalaman & peluang (belajar keterampilan, memulai usaha kecil) sering memberi 'pengembalian' jangka panjang yang besar.",hint:"Apa yang bisa kamu tabung yang membuka kemampuan baru, bukan hanya menambah barang?"},
{n:55,type:"mcq",micro:"Menyeimbangkan banyak tujuan",q:"Kamu punya 4 tujuan & tabungan bulanan terbatas. Pendekatan:",options:["Bagi rata ke keempatnya dengan jumlah persis sama, tanpa memedulikan mana yang lebih penting atau lebih mendesak waktunya","Fokus hanya pada satu tujuan dan abaikan tiga lainnya selamanya, bahkan jika tenggatnya sebenarnya sudah dekat sekali","Beri porsi lebih besar ke yang paling penting/mendesak, porsi kecil ke sisanya (atau tunda beberapa) — jangan bagi terlalu tipis sampai tidak ada yang tercapai"],answer:2,explain:"Membagi terlalu tipis membuat semua tujuan bergerak sangat lambat. Memprioritaskan mempercepat yang terpenting.",hint:"Lebih baik satu tujuan tercapai bulan ini, atau empat tujuan sama-sama 'hampir tidak bergerak'?"},
{n:56,type:"mcq",micro:"Rasa 'cukup' & tujuan",q:"Setelah mencapai sebuah tujuan tabungan, kebiasaan yang sehat:",options:["Rayakan & nikmati pencapaian itu, lalu tetapkan tujuan berikutnya — menjaga momentum menabung","Berhenti menabung selamanya karena tujuannya sudah tercapai dan tidak ada lagi alasan untuk menyisihkan uang berikutnya","Langsung menghabiskan semua tabungan lain juga untuk merayakan, supaya tidak ada uang tersisa yang bisa menggoda"],answer:0,explain:"Mencapai tujuan adalah bukti bahwa kamu bisa. Menetapkan tujuan baru menjaga kebiasaan tetap hidup.",hint:"Apa yang menjaga otot menabung tetap terlatih setelah satu tujuan selesai?"},
{n:57,type:"tf",micro:"Menabung melindungi dari utang buruk",q:"Benar atau Salah: Punya tabungan darurat tidak berpengaruh pada apakah seseorang terpaksa mengambil pinjaman berbunga tinggi saat menghadapi pengeluaran mendadak.",answer:false,explain:"Dana darurat adalah alternatif dari berutang. Orang yang punya tabungan darurat jauh lebih kecil kemungkinannya terpaksa meminjam dengan bunga tinggi saat kejutan datang.",hint:"Kalau alat sekolah rusak & kamu punya tabungan darurat, apakah kamu perlu meminjam?"},
{n:58,type:"mcq",micro:"Menabung untuk masa depan yang jauh",q:"Menabung untuk tujuan bertahun-tahun ke depan (kuliah, modal usaha, masa dewasa) terasa sulit karena hasilnya jauh. Yang membantu:",options:["Tidak menabung untuk hal yang masih jauh, karena yang terpenting adalah memenuhi keinginan yang ada di depan mata dulu","Otomatisasi, tonggak berkala, mengaitkan tujuan dengan gambaran hidup yang kamu inginkan, & memakai bunga majemuk (mulai lebih awal)","Menunggu sampai tujuannya terasa 'lebih dekat' baru mulai menabung, karena menabung lebih awal pasti sia-sia belaka"],answer:1,explain:"Tujuan jangka sangat panjang paling terbantu oleh sistem yang tidak bergantung motivasi harian, plus dimulai sedini mungkin.",hint:"Bagaimana membuat menabung untuk sesuatu 5 tahun lagi tetap terjadi hari ini?"},
{n:59,type:"mcq",micro:"Menilai kemajuan dengan jujur",q:"Di akhir bulan, kamu meninjau & ternyata tabungan meleset dari target. Sikap yang produktif:",options:["Menyerah pada semua tujuan tabungan, karena satu kali meleset berarti kamu memang tidak cocok untuk menabung sama sekali","Berpura-pura bahwa target sudah tercapai dan tidak mengubah apa pun, supaya suasana hati tetap tenang dan senang","Cari sebabnya (pengeluaran tak terduga? porsi terlalu besar? lupa menyisihkan?), sesuaikan rencana bulan depan — bukan menyerah"],answer:2,explain:"Meleset adalah data. Menyesuaikan rencana berdasarkan sebabnya adalah cara kebiasaan menabung matang.",hint:"Bagaimana rencana bulan depan bisa lebih realistis?"},
{n:60,type:"open",micro:"Menganalisis kegagalan menabung",q:"Seorang teman berkata: 'Aku niat menabung Rp30.000 tiap minggu, tapi tiga bulan berlalu & tabunganku hampir nol. Aku selalu berpikir akan menabung dari sisa uang saku, tapi tidak pernah ada sisa.' Analisis: (1) apa kesalahan strateginya, (2) apa yang seharusnya ia lakukan, (3) rancang sistem konkret untuknya, (4) bagaimana ia menjaga agar tidak memakai tabungan itu.",explain:"Jawaban baik mengenali kesalahan 'menabung dari sisa' & 'mengandalkan niat', mengusulkan 'bayar diri sendiri dulu' + mulai dari jumlah realistis, merancang sistem dengan pemicu tetap + wadah terpisah yang dipegang orang lain + pelacakan + tujuan visual, & pengaman terhadap godaan memakainya.",hint:"Masalah intinya: menabung yang menunggu sisa & bergantung pada ingatan hampir selalu gagal.",sample:"(1) Kesalahan: ia menabung 'dari sisa' — tabungan menunggu sampai semua pengeluaran selesai, & seperti biasa tidak ada sisa. Ia juga mengandalkan 'niat & ingat' setiap minggu, bukan sistem. (2) Seharusnya: bayar diri sendiri dulu — sisihkan Rp30.000 begitu uang saku diterima, SEBELUM belanja apa pun; & mungkin mulai dari jumlah lebih kecil (Rp15.000) yang pasti bisa, lalu naikkan. (3) Sistem: setiap Senin pagi sepulang menerima uang saku, langsung masukkan Rp20.000 ke amplop 'tabungan' yang dititipkan ke orang tua (bukan disimpan sendiri). Sisa Rp40.000 untuk seminggu. Catat di ponsel tiap setoran + total. Tetapkan tujuan konkret (mis. sepeda) & tempel gambarnya. (4) Menjaga tidak dipakai: amplop dipegang orang tua sehingga butuh usaha & alasan untuk mengambilnya; buat aturan pribadi 'hanya diambil untuk tujuan ini atau darurat sungguhan'; lihat kemajuan tiap minggu agar sayang menghancurkannya."},
{n:61,type:"mcq",micro:"Menabung berlebihan (jarang, tapi ada)",q:"Menabung sampai tidak pernah membeli hal yang benar-benar meningkatkan hidup (buku, alat hobi, sesekali berkumpul dengan teman)...",options:["Bisa jadi tidak seimbang — uang adalah alat untuk hidup yang baik, bukan tujuan itu sendiri; menabung & menikmati keduanya penting","Selalu merupakan strategi terbaik, karena makin sedikit uang yang dikeluarkan makin cepat kamu menjadi kaya raya","Tidak mungkin terjadi pada siapa pun, sebab orang yang menabung pasti selalu punya cukup uang untuk membeli apa saja"],answer:0,explain:"Tujuan menabung adalah keamanan & kebebasan untuk hal yang berarti — bukan menimbun uang tanpa pernah memakainya untuk hidup yang baik.",hint:"Untuk apa sebenarnya kamu menabung?"},
{n:62,type:"tf",micro:"Menabung tidak menjamin kebahagiaan, tapi memberi pilihan",q:"Benar atau Salah: Menabung tidak otomatis membuat orang bahagia, tapi memberi lebih banyak pilihan & lebih sedikit tekanan saat masalah keuangan datang.",answer:true,explain:"Tabungan adalah penyangga & pembuka pilihan, bukan sumber kebahagiaan langsung. Nilainya ada pada kebebasan & ketenangan yang diberikannya.",hint:"Apa yang tabungan berikan: kegembiraan langsung, atau lebih sedikit kekhawatiran & lebih banyak pilihan?"},
{n:63,type:"mcq",micro:"Godaan 'aku akan menabung lebih banyak nanti'",q:"Pikiran 'aku akan mulai menabung serius nanti saat uangku lebih banyak' berbahaya karena...",options:["Menabung sekarang tidak ada gunanya karena jumlahnya terlalu kecil, jadi lebih baik menunggu sampai penghasilan sudah besar","Pengeluaran cenderung tumbuh mengikuti pemasukan; kalau tidak bisa menyisihkan Rp5.000 dari Rp50.000, sering juga sulit menyisihkan Rp50.000 dari Rp500.000 — kebiasaan yang penting, bukan jumlahnya","Nanti pasti lebih mudah menabung karena pengeluaran tidak pernah ikut bertambah ketika penghasilan seseorang bertambah"],answer:1,explain:"'Aku akan menabung nanti' sering tidak pernah datang karena keinginan ikut membesar. Membangun kebiasaan sekarang, meski kecil, lebih penting.",hint:"Apakah orang yang tidak menyisihkan 10% dari sedikit biasanya menyisihkan 10% dari banyak?"},
{n:64,type:"mcq",micro:"Menabung & keadaan keluarga sulit",q:"Kalau keluargamu sedang kesulitan & kamu ingin membantu dengan uang sakumu...",options:["Berikan semua uang sakumu tanpa memberi tahu siapa pun, karena membantu keluarga harus dilakukan diam-diam dan tanpa sisa untuk dirimu","Abaikan saja keadaan keluarga, sebab urusan uang keluarga bukan urusan anak dan sama sekali tidak perlu kamu pikirkan","Itu pilihan yang mulia; bicarakan dengan orang tua tentang cara terbaik membantu, & tetap sisakan sedikit untuk kebutuhanmu sendiri (transport, alat sekolah)"],answer:2,explain:"Membantu keluarga adalah nilai yang baik. Melakukannya dengan komunikasi & tanpa mengorbankan kebutuhan dasarmu sendiri adalah caranya.",hint:"Bagaimana membantu keluarga sambil tetap bisa berangkat sekolah?"},
{n:65,type:"tf",micro:"Tidak ada satu rasio menabung yang benar",q:"Benar atau Salah: Berapa persen yang sebaiknya ditabung berbeda antar orang tergantung penghasilan, tanggungan, tujuan, & keadaan — 'menabung 20%' hanyalah titik awal.",answer:true,explain:"Anak yang harus membantu biaya keluarga & anak yang tidak punya situasi berbeda. Sesuaikan, jangan salin mentah.",hint:"Apakah anak dengan uang saku Rp20.000 & Rp200.000 punya rasio yang sama?"},
{n:66,type:"mcq",micro:"Menabung untuk tujuan orang lain (batas)",q:"Kamu menabung untuk hadiah besar bagi teman. Sebelum berkomitmen:",options:["Pastikan itu sesuai kemampuanmu & tidak mengorbankan kebutuhan/dana daruratmu; kasih sayang tidak diukur dari harga hadiah","Habiskan seluruh tabunganmu untuk membeli hadiah termahal, karena harga hadiah menunjukkan seberapa besar kasih sayangmu pada teman","Berutang kepada orang lain agar bisa membeli hadiah yang mengesankan, lalu cicil pelan-pelan dari uang sakumu bulan depan"],answer:0,explain:"Memberi adalah baik, tapi dalam batas kemampuan. Berutang atau mengorbankan kebutuhanmu untuk hadiah bukan kebijaksanaan.",hint:"Apakah nilai persahabatan diukur dari harga hadiah?"},
{n:67,type:"mcq",micro:"Menabung & 'FOMO'",q:"Kamu menabung untuk tujuan, lalu ada 'kesempatan langka' (barang diskon besar, acara) yang mendorongmu memakai tabungan. Sikap yang tepat:",options:["Selalu abaikan semua kesempatan yang datang, karena tabungan yang sudah ditetapkan tujuannya tidak boleh disentuh dalam kondisi apa pun","Jeda; nilai apakah 'kesempatan' ini benar-benar sepadan dengan mundurnya tujuanmu — 'kesempatan langka' sering tidak sekritis yang terasa","Selalu ambil setiap kesempatan langka yang muncul, sebab kesempatan seperti itu jarang kembali dan tabungan bisa dikumpulkan lagi kapan saja"],answer:1,explain:"Rasa takut ketinggalan (FOMO) sering dilebih-lebihkan oleh penjual & suasana. Jeda membantu menilai dengan tenang.",hint:"Berapa banyak 'kesempatan sekali seumur hidup' yang kamu lihat setiap bulan?"},
{n:68,type:"tf",micro:"Menabung otomatis mengatasi kelemahan kemauan",q:"Benar atau Salah: Menabung yang berhasil harus sepenuhnya bergantung pada disiplin & kemauan untuk memutuskan menabung setiap kali uang masuk, bukan pada sistem otomatis atau rutin.",answer:false,explain:"Sebaliknya. Kemauan manusia sering lemah saat menghadapi godaan langsung. Sistem otomatis/rutin yang tidak butuh keputusan tiap kali jauh lebih andal.",hint:"Apa yang lebih kuat: niat baik setiap hari, atau sistem yang berjalan sendiri?"},
{n:69,type:"mcq",micro:"Menabung vs pengalaman berharga",q:"Kamu punya kesempatan ikut kegiatan berharga (kemah belajar, lomba) yang butuh biaya & memakan sebagian tabunganmu. Pertimbangan:",options:["Selalu tolak apa pun yang mengurangi tabungan, karena menabung lebih penting daripada pengalaman belajar apa pun juga dalam hidup","Selalu ambil apa pun yang menyenangkan tanpa menimbang, sebab tujuan tabungan bisa ditunda tanpa batas waktu yang jelas","Nilai pengalamannya (belajar, relasi, kenangan) vs mundurnya tujuan tabungan; sebagian pengalaman memberi 'pengembalian' jangka panjang yang layak"],answer:2,explain:"Tabungan bisa dipakai untuk pengalaman yang benar-benar bernilai. Yang penting: keputusan sadar yang menimbang, bukan impuls.",hint:"Apakah tabungan hanya untuk barang, atau juga untuk pengalaman yang membentuk dirimu?"},
{n:70,type:"order",micro:"Memutuskan apakah memakai tabungan",q:"Sesuatu mendorongmu memakai tabungan tujuan. Urutkan langkah menimbangnya.",items:["Berhenti & jeda — jangan putuskan di puncak keinginan/tekanan","Ingat: tujuan tabungan ini untuk apa, sudah berapa lama kutabung, & berapa lagi sampai tercapai","Nilai: apakah hal yang mendorong ini benar-benar sepadan dengan mundurnya tujuan?","Putuskan; kalau memakainya, buat rencana mengganti/menyesuaikan tenggat"],answer:[0,1,2,3],explain:"Jeda → ingat konteks tujuan → nilai kesepadanan → putuskan dengan rencana pemulihan.",hint:"Jangan biarkan puncak dorongan yang memutuskan."},
{n:71,type:"mcq",micro:"Menabung & inflasi jangka pendek",q:"Untuk dana darurat yang mungkin dipakai kapan saja, kekhawatiran inflasi...",options:["Kurang mendesak dibanding keamanan & ketersediaan — dana darurat harus utuh & siap diambil, meski nilainya sedikit tergerus inflasi","Sangat mendesak, jadi sebaiknya dana darurat ditaruh di tempat berisiko tinggi supaya cepat berlipat ganda mengalahkan inflasi","Berarti dana darurat sama sekali tidak perlu disiapkan, sebab nilainya pasti akan habis dimakan inflasi bila disimpan lama"],answer:0,explain:"Untuk uang yang mungkin dibutuhkan segera, prioritasnya keamanan & likuiditas, bukan mengalahkan inflasi.",hint:"Apa yang lebih penting untuk uang darurat: tumbuh maksimal, atau utuh & tersedia saat kamu perlu?"},
{n:72,type:"mcq",micro:"Menabung sebagai kebiasaan keluarga",q:"Kalau keluargamu tidak punya kebiasaan menabung, kamu tetap bisa...",options:["Menunggu keluargamu berubah dulu dan mulai menabung bersama, baru kemudian kamu ikut menyisihkan sebagian uang sakumu","Membangun kebiasaanmu sendiri dengan uang sakumu, & mungkin berbagi apa yang kamu pelajari — kebiasaan bisa dimulai dari siapa saja","Tidak bisa menabung sama sekali karena keluargamu tidak punya kebiasaan itu, sehingga kamu juga pasti tidak akan mampu"],answer:1,explain:"Kebiasaan keuangan yang baik bisa dimulai oleh siapa pun, kapan pun, terlepas dari lingkungan.",hint:"Apakah kamu harus menunggu orang lain sebelum membangun kebiasaan baikmu sendiri?"},
{n:73,type:"tf",micro:"Menabung membangun disiplin yang meluas",q:"Benar atau Salah: Kemampuan menetapkan tujuan, menahan kepuasan sesaat, & konsisten menuju tujuan — yang dilatih lewat menabung — juga membantu di bidang lain seperti belajar & mengejar cita-cita.",answer:true,explain:"Menabung melatih 'otot' penundaan kepuasan & ketekunan yang berguna untuk banyak hal dalam hidup.",hint:"Apakah keterampilan 'konsisten menuju tujuan jauh' hanya berguna untuk uang?"},
{n:74,type:"mcq",micro:"Menabung & pemasukan yang meningkat",q:"Kalau uang sakumu naik (atau kamu mulai mendapat penghasilan), kebiasaan yang menjaga keuanganmu sehat:",options:["Naikkan hanya pengeluaranmu saja agar kamu bisa menikmati hidup lebih nyaman, sedangkan porsi tabungan dibiarkan tetap sama","Habiskan seluruh kenaikan itu untuk keinginan, karena kenaikan uang saku memang pantas dirayakan dengan berbelanja","Naikkan juga porsi tabungan (bukan hanya pengeluaran), sehingga sebagian kenaikan langsung memperkuat masa depanmu"],answer:2,explain:"Membiarkan tabungan tumbuh seiring pemasukan (bukan hanya gaya hidup) adalah cara membangun keamanan jangka panjang.",hint:"Ke mana sebaiknya sebagian 'kenaikan pemasukan' pergi?"},
{n:75,type:"mcq",micro:"Menyeimbangkan menabung & memberi",q:"Menyertakan porsi 'berbagi' dalam rencana tabungan...",options:["Adalah pilihan pribadi yang banyak orang anggap bagian dari mengelola uang dengan baik — besarnya sesuai nilai & kemampuan","Selalu mengurangi keamananmu","Wajib 50%"],answer:0,explain:"Banyak rencana keuangan menyertakan bagian untuk membantu orang lain. Ini soal nilai, bukan kewajiban tetap.",hint:"Apakah mengelola uang hanya tentang diri sendiri?"},
{n:76,type:"tf",micro:"Kemajuan kecil menumpuk",q:"Benar atau Salah: Kecepatan pertumbuhan tabungan selalu tetap sama; menabung konsisten & bunga majemuk tidak membuat pertumbuhannya mempercepat seiring waktu.",answer:false,explain:"Efek 'bola salju': makin lama menabung, makin besar dasar yang tumbuh, & (dengan bunga majemuk) makin terasa hasilnya — pertumbuhannya justru bisa mempercepat.",hint:"Apakah bola salju menggelinding lebih cepat menambah ukuran di awal atau setelah sudah besar?"},
{n:77,type:"mcq",micro:"Menabung untuk hal yang tidak pasti",q:"Menabung untuk kemungkinan masa depan yang belum pasti (kuliah, pindah, memulai usaha) tetap berguna karena...",options:["Lebih baik tidak menyiapkan apa pun untuk hal yang belum pasti terjadi, dan uangnya langsung dipakai untuk kebutuhan hari ini","Kalau kesempatan itu datang, kamu siap; kalau tidak, uangnya bisa dialihkan ke tujuan lain — menabung memberi opsi","Menabung untuk hal yang tidak pasti selalu sia-sia, sebab kalau kesempatannya tidak datang uangnya akan hilang percuma"],answer:1,explain:"Tabungan untuk 'kemungkinan' adalah investasi pada fleksibilitas & kesiapan menghadapi peluang.",hint:"Apa yang kamu punya kalau peluang datang & kamu sudah menabung, vs kalau belum?"},
{n:78,type:"mcq",micro:"Menabung & rasa aman",q:"Bagi banyak orang, manfaat terbesar dana darurat bukan uangnya, melainkan...",options:["Bunga yang diterima","Bisa dipamerkan","Ketenangan pikiran — mengetahui bahwa kejutan tidak akan langsung menjadi krisis"],answer:2,explain:"Dana darurat mengurangi kecemasan finansial. Nilai psikologisnya sering lebih besar dari nilai bunganya.",hint:"Bagaimana perasaanmu tentang kejutan biaya kalau kamu punya penyangga vs tidak?"},
{n:79,type:"mcq",micro:"Menabung yang dikomunikasikan",q:"Memberi tahu orang tua atau teman tepercaya tentang tujuan tabunganmu bisa membantu karena...",options:["Mereka bisa mengingatkan, mendukung, & tidak sengaja menggodamu untuk membelanjakannya — akuntabilitas sosial membantu konsistensi","Membuat tujuanmu berubah menjadi milik mereka, sehingga merekalah yang berhak memutuskan kapan dan bagaimana uangmu dipakai nantinya","Tidak ada manfaatnya sama sekali, sebab tujuan tabungan sebaiknya dirahasiakan dari semua orang agar tidak ada yang meminjam uangmu"],answer:0,explain:"Berbagi tujuan dengan orang yang mendukung menciptakan akuntabilitas ringan yang membantu bertahan.",hint:"Apakah lebih mudah menaati komitmen yang diketahui orang lain?"},
{n:80,type:"open",micro:"Menganalisis dilema menabung",q:"Kamu sudah menabung Rp250.000 dari Rp300.000 untuk sepatu bola (tinggal 2 minggu). Lalu ada karyawisata sekolah opsional yang bagus & menarik seharga Rp200.000, tenggat bayar 3 hari lagi. Uang tabungan sepatumu bisa menutupinya. Analisis: (1) apa yang dipertaruhkan di tiap pilihan, (2) pertanyaan yang membantu memutuskan, (3) apakah ada opsi ketiga, (4) bagaimana kamu memutuskan & rencana pemulihannya.",explain:"Jawaban baik menimbang apa yang dipertaruhkan (pengalaman unik vs tujuan hampir tercapai + kemunduran), mengajukan pertanyaan yang tepat (keunikan, urgensi, kemampuan memulihkan), mencari opsi ketiga (pinjaman keluarga terencana, tambah pemasukan, pinjam sepatu), & memutuskan dengan rencana pemulihan konkret.",hint:"Jarang benar-benar hanya 'A atau B' — & keputusan apa pun sebaiknya disertai rencana memulihkan tabungan.",sample:"(1) Kalau pakai untuk karyawisata: dapat pengalaman & kenangan bersama teman, tapi tujuan sepatu mundur ~8 minggu lagi (harus menabung ulang Rp200.000) & rasa 'hampir tercapai' hilang. Kalau tetap untuk sepatu: sepatu tercapai 2 minggu lagi, tapi melewatkan karyawisata yang mungkin tidak terulang. (2) Pertanyaan: Seberapa penting/unik karyawisata ini bagiku (sekali saja? teman dekat ikut?)? Seberapa mendesak sepatu (ada lomba? sepatu lama masih bisa dipakai?)? Bisakah aku menabung ulang Rp200.000 dalam waktu wajar? (3) Opsi ketiga: minta bantuan/pinjaman ke orang tua untuk karyawisata yang kubayar dari tabungan mendatang; cari uang tambahan (bantu usaha, jual barang yang tidak dipakai) untuk salah satunya; ikut karyawisata sebagian biaya (kalau boleh); pinjam sepatu bola dari teman sementara. (4) Keputusan (contoh): karena sepatu lamaku masih bisa dipakai & karyawisata ini hanya sekali dengan teman-teman dekat, aku ikut karyawisata — TAPI dengan rencana: aku bicara dengan orang tua apakah bisa menutup Rp100.000 sebagai 'pinjaman' yang kuganti dari uang saku Rp25.000/minggu selama 4 minggu, sehingga tabungan sepatu hanya mundur ~4 minggu, bukan 8. Kalau orang tua tidak bisa, aku cari uang tambahan dengan membantu paman akhir pekan ini."},
{n:81,type:"mcq",micro:"Kerangka menabung",q:"Kerangka singkat untuk menabung dengan baik:",options:["Tunggu sampai kamu sudah kaya raya baru mulai menabung secara serius, sebab menabung sedikit tidak ada gunanya dan hanya membuang tenaga","Bayar diri sendiri dulu (sisihkan begitu uang masuk); tujuan yang jelas & terukur dengan tenggat; wadah terpisah & agak sulit dijangkau; lacak kemajuan & rayakan tonggak; mulai sedini mungkin (bunga majemuk); & seimbangkan dengan menikmati sebagian","Menabung dari sisa uang yang tidak terpakai, tanpa tujuan yang jelas, dan menyimpannya di dompet supaya selalu mudah diambil kapan saja"],answer:1,explain:"Bayar diri sendiri dulu + tujuan jelas + wadah terpisah + lacak + mulai dini + seimbang = inti menabung yang berhasil.",hint:"Gabungkan: sisihkan dulu + tujuan jelas + wadah terpisah + lacak + mulai dini + seimbang."},
{n:82,type:"mcq",micro:"Menabung pada tingkat penghasilan berapa pun",q:"'Menabung' relevan bagi...",options:["Hanya orang kaya","Hanya orang dewasa yang bekerja","Semua orang, pada tingkat pemasukan berapa pun — yang berubah hanya jumlahnya, bukan pentingnya kebiasaan"],answer:2,explain:"Kebiasaan menyisihkan sebagian & bergerak menuju tujuan berlaku universal. Membangunnya sejak muda memberi keuntungan waktu.",hint:"Apakah kebiasaan menyisihkan hanya untuk yang punya banyak?"},
{n:83,type:"tf",micro:"Menabung adalah keterampilan yang dilatih",q:"Benar atau Salah: Kemampuan menabung secara konsisten menuju tujuan berkembang dengan latihan, sistem yang baik, & meninjau hasil — bukan sifat bawaan yang tetap.",answer:true,explain:"Setiap tujuan yang kamu tetapkan, tabung, & tinjau memperkuat kebiasaan & kepercayaan dirimu bahwa kamu bisa.",hint:"Apakah orang menjadi penabung yang lebih baik setelah berlatih & merefleksikan?"},
{n:84,type:"mcq",micro:"Menabung & keputusan besar masa depan",q:"Kebiasaan menabung sejak muda membantu keputusan besar nanti (kuliah, usaha, tempat tinggal) karena...",options:["Kamu punya modal awal & kebiasaan disiplin, sehingga lebih banyak pilihan & lebih sedikit ketergantungan pada utang mahal","Tidak berpengaruh pada keputusan besar apa pun, karena kebiasaan menabung ketika muda akan hilang sendiri saat seseorang dewasa nanti","Keputusan besar seperti kuliah dan usaha sebenarnya tidak membutuhkan uang sama sekali, jadi menabung tidak akan menentukan apa pun"],answer:0,explain:"Tabungan yang terbangun memberi 'landasan' untuk mengambil peluang besar tanpa terjebak utang yang membebani.",hint:"Siapa yang punya lebih banyak pilihan saat kesempatan besar datang: yang menabung sejak muda atau yang belum pernah?"},
{n:85,type:"order",micro:"Menyusun rencana tabungan menyeluruh",q:"Urutkan langkah menyusun rencana tabungan menyeluruh.",items:["Amankan kebutuhan bulanan & bangun dana darurat kecil lebih dulu","Daftar tujuan (pendek & panjang) dengan jumlah & tenggat, urutkan prioritas","Tetapkan jumlah/persentase berkala untuk tiap tujuan, dalam batas pemasukan","Otomatiskan/rutinkan, pisahkan wadah, lacak, tinjau berkala, & sesuaikan"],answer:[0,1,2,3],explain:"Kebutuhan & darurat dulu → daftar & prioritas tujuan → alokasi berkala → sistem, pelacakan, & tinjauan.",hint:"Amankan yang mendasar sebelum mengejar tujuan yang lebih besar."},
{n:86,type:"mcq",micro:"Mengajari menabung",q:"Cara terbaik membantu adik/teman mulai menabung:",options:["Suruh saja ia menabung tanpa tujuan tertentu, sebab yang penting uangnya terkumpul dulu dan tujuannya bisa dipikirkan belakangan","Bantu ia menetapkan satu tujuan kecil & konkret yang ia inginkan, tunjukkan cara menyisihkan sedikit rutin, & rayakan saat tercapai — sukses pertama membangun kebiasaan","Beri ia ceramah panjang tentang pentingnya menabung sampai ia mengerti, tanpa membantunya memilih tujuan atau cara memulai"],answer:1,explain:"Pengalaman berhasil menabung untuk sesuatu yang benar-benar diinginkan adalah guru terbaik.",hint:"Apa yang membuat seseorang percaya 'aku bisa menabung'?"},
{n:87,type:"tf",micro:"Menabung melengkapi keterampilan keuangan lain",q:"Benar atau Salah: Menabung bekerja paling baik bersama keterampilan lain — membedakan kebutuhan/keinginan, membuat anggaran, menjadi konsumen cerdas, & menghindari utang buruk.",answer:true,explain:"Menabung bukan berdiri sendiri; ia didukung oleh pengeluaran yang bijak & anggaran yang menyisakan ruang untuk menabung.",hint:"Bisakah kamu menabung konsisten tanpa mengatur pengeluaran?"},
{n:88,type:"mcq",micro:"Menutup: menabung & tujuan",q:"Sikap paling berguna:",options:["Menabung dari sisa uang yang tidak terpakai, tanpa tujuan, dan berharap suatu hari tabungan akan terkumpul sendiri tanpa perlu direncanakan atau dicatat","Tunda menabung sampai penghasilan sudah besar, jangan pisahkan wadah, jangan lacak kemajuan, dan pakai seluruh dana darurat untuk keinginan yang muncul lebih dulu","Tetapkan tujuan yang jelas & bermakna bagimu; bayar diri sendiri dulu dengan sistem yang tidak bergantung kemauan harian; pisahkan wadah & lacak kemajuan; amankan dana darurat; mulai sedini mungkin; & seimbangkan menabung dengan menikmati sebagian hidup sekarang"],answer:2,explain:"Inti: tujuan bermakna + bayar diri sendiri dulu + sistem + wadah terpisah + lacak + darurat + mulai dini + seimbang.",hint:"Gabungkan: tujuan bermakna + sisihkan dulu + sistem + darurat + mulai dini + seimbang."},
{n:89,type:"mcq",micro:"Ringkasan: menabung & tujuan keuangan",q:"Rangkuman paling tepat:",options:["Menabung adalah menyisihkan sebagian uang untuk tujuan yang jelas (dana darurat, jangka pendek, jangka panjang) & untuk keamanan; strategi kunci: bayar diri sendiri dulu, sistem yang tidak bergantung kemauan harian, wadah terpisah, melacak & merayakan kemajuan, mulai sedini mungkin (bunga majemuk), sesuaikan saat keadaan berubah, & seimbangkan dengan menikmati hidup sekarang — & ini keterampilan yang menguat dengan latihan","Menabung berarti tidak pernah membelanjakan uang untuk apa pun sama sekali; strategi kuncinya adalah menahan diri sepenuhnya dari semua kesenangan, tidak perlu tujuan, tidak perlu dilacak, dan tidak ada gunanya dimulai sedini mungkin","Menabung hanya untuk orang dewasa yang sudah kaya; anak sekolah tidak perlu menyisihkan uang karena jumlahnya terlalu kecil, tidak perlu tujuan, tidak perlu dana darurat, dan tidak perlu belajar kebiasaan itu sama sekali"],answer:0,explain:"Menabung = menyisihkan untuk tujuan & keamanan, dengan strategi (bayar diri sendiri dulu, sistem, wadah terpisah, lacak, mulai dini, sesuaikan, seimbang) yang bisa dilatih.",hint:"Gabungkan: menyisihkan untuk tujuan & keamanan + strategi kunci + keterampilan yang dilatih."},
{n:90,type:"tf",micro:"Menabung memberi kendali atas uang",q:"Benar atau Salah: Menabung menuju tujuan tidak mengubah hubunganmu dengan uang — kamu tetap sekadar bereaksi pada apa yang terjadi (reaktif), bukan memutuskan ke mana uangmu pergi.",answer:false,explain:"Menabung dengan tujuan justru mengubah hubunganmu dengan uang dari 'reaktif' menjadi 'terarah': kamu mengambil kemudi, & uang melayani rencanamu, bukan sekadar habis mengikuti keadaan.",hint:"Siapa yang memutuskan ke mana uang pergi: kamu, atau keadaan sesaat?"},
{n:91,type:"mcq",micro:"Tiga prinsip praktis",q:"Tiga prinsip praktis menabung:",options:["Tunggu sampai kaya baru menabung; jangan pernah menikmati apa pun dari uangmu; dan berutang saja untuk mencapai setiap tujuan yang kamu inginkan sekarang","Bayar diri sendiri dulu (sisihkan begitu uang masuk); tetapkan tujuan yang jelas & terukur; & pakai sistem (wadah terpisah, rutin/otomatis, lacak) agar tidak bergantung kemauan harian","Menabung dari sisa saja; tanpa tujuan yang jelas; dan simpan semuanya di dompet agar mudah diambil kapan pun kamu ingin membelanjakannya"],answer:1,explain:"Bayar diri sendiri dulu + tujuan jelas + sistem = inti menabung yang berhasil.",hint:"Gabungkan: sisihkan dulu + tujuan jelas + sistem."},
{n:92,type:"open",micro:"Kapstone: rencana tabungan pribadi 6 bulan",q:"Buat rencana tabungan pribadi untuk 6 bulan. Sertakan: (1) perkiraan total pemasukan, (2) kebutuhan bulanan yang harus diamankan, (3) target dana darurat & rencana membangunnya, (4) 1–2 tujuan lain (pendek/panjang) dengan jumlah, tenggat, & jumlah berkala, (5) sistem menyisihkan (pemicu tetap, wadah, cara melacak), (6) aturan untuk uang tak terduga, (7) porsi kecil untuk dinikmati agar berkelanjutan, (8) kapan & bagaimana kamu meninjau tiap bulan.",explain:"Kapstone menggabungkan semuanya: hitung pemasukan, amankan kebutuhan, prioritaskan dana darurat, tetapkan tujuan realistis dengan jumlah berkala (menyesuaikan bila total tidak muat), sistem 'bayar diri sendiri dulu' + wadah terpisah + pelacakan, aturan uang kejutan, porsi menikmati, & tinjauan bulanan.",hint:"Pastikan total (kebutuhan + darurat + tujuan + nikmati) ≤ pemasukan; kalau tidak muat, sesuaikan tenggat atau jumlah tujuan — jangan korbankan kebutuhan atau darurat.",sample:"Contoh: (1) Pemasukan: uang saku Rp60.000/minggu ≈ Rp240.000/bulan + bantu paman Rp80.000/bulan = Rp320.000/bulan; 6 bulan ≈ Rp1.920.000. (2) Kebutuhan/bulan: transport Rp90.000, makan Rp90.000, keperluan sekolah Rp30.000 = Rp210.000. (3) Dana darurat: target Rp180.000; sisihkan Rp30.000/bulan → tercapai bulan ke-6 (prioritas pertama). (4) Tujuan lain: sepatu lari Rp270.000 — Rp22.500/bulan tidak cukup dalam 6 bulan bersama darurat, jadi mulai bulan ke-4 setelah darurat lebih ringan, atau alokasikan Rp15.000/bulan (total Rp90.000) lalu lanjut setelah 6 bulan; kado ibu Rp80.000 di bulan ke-3 — Rp27.000/bulan selama 3 bulan. (5) Sistem: setiap Senin pagi setelah menerima uang saku, pisahkan porsi darurat + tujuan ke amplop berlabel yang dipegang ibu, SEBELUM belanja; catat di aplikasi ponsel tiap setoran + total. (6) Uang tak terduga: 60% ke tujuan terdekat tenggatnya, 40% dinikmati. (7) Sisakan ~Rp10.000/minggu untuk jajan/hiburan agar tidak jenuh. (8) Tiap akhir bulan: bandingkan setoran nyata vs rencana, cek saldo tiap amplop, cari sebab bila meleset, sesuaikan bulan berikutnya."},
{n:93,type:"mcq",micro:"Menilai rencana tabungan",q:"Sebuah rencana tabungan yang baik...",options:["Menyisihkan 90% dari semua uang yang diterima dan melarang diri menikmati kesenangan apa pun, supaya tabungan cepat sekali bertambah banyak","Menabung dari sisa uang saja tanpa target yang jelas, tanpa dana darurat, dan tanpa sistem rutin, lalu berharap tabungan terkumpul dengan sendirinya","Realistis (muat dalam pemasukan), menaruh dana darurat & kebutuhan sebagai prioritas, punya tujuan terukur, memakai sistem otomatis/rutin, & menyisakan sedikit untuk dinikmati agar bisa bertahan"],answer:2,explain:"Rencana yang bertahan adalah yang seimbang & bersistem, bukan yang paling ekstrem atau paling longgar.",hint:"Apa yang membuat rencana tabungan benar-benar dijalankan berbulan-bulan?"},
{n:94,type:"mcq",micro:"Menabung & identitas",q:"Orang yang berpikir 'aku adalah orang yang menabung' (bukan sekadar 'aku sedang mencoba menabung')...",options:["Cenderung lebih konsisten, karena menabung menjadi bagian dari siapa mereka, bukan tugas yang berat","Tidak ada bedanya","Lebih mungkin menyerah"],answer:0,explain:"Kebiasaan yang menjadi bagian identitas lebih tahan lama daripada yang dirasa sebagai perjuangan terus-menerus.",hint:"Apa bedanya 'aku mencoba berhenti begadang' & 'aku orang yang tidur cukup'?"},
{n:95,type:"tf",micro:"Menabung kecil sejak dini mengalahkan menabung besar terlambat",q:"Benar atau Salah: Karena bunga majemuk & kekuatan kebiasaan, menabung jumlah kecil sejak muda sering menghasilkan lebih banyak (& kebiasaan lebih kuat) daripada berniat menabung jumlah besar 'nanti kalau sudah mapan'.",answer:true,explain:"Waktu adalah faktor terbesar dalam pertumbuhan majemuk, & kebiasaan yang dimulai dini lebih mengakar.",hint:"Mana yang tumbuh lebih besar: bola salju kecil yang menggelinding lama, atau bola besar yang baru mulai menggelinding?"},
{n:96,type:"mcq",micro:"Menabung untuk memberi & dampak",q:"Menyisihkan sebagian tabungan secara rutin untuk membantu orang lain...",options:["Bukan bentuk menabung sama sekali, karena uang yang disisihkan untuk orang lain berarti hilang dan tidak ada gunanya bagi dirimu","Bisa berdampak nyata seiring waktu, sama seperti tabungan kecil menumpuk jadi besar — nilainya pada keteraturannya","Tidak berdampak apa pun kecuali jumlahnya besar, sehingga menyisihkan sedikit demi sedikit secara rutin hanyalah buang-buang waktu"],answer:1,explain:"Kebiasaan berbagi yang konsisten, seperti menabung yang konsisten, menghasilkan efek kumulatif.",hint:"Kalau menabung Rp5.000/minggu jadi besar setahun, bagaimana dengan berbagi Rp5.000/minggu?"},
{n:97,type:"mcq",micro:"Inti yang dibawa pulang",q:"Satu gagasan inti tentang menabung:",options:["Menabung hanya berguna kalau kamu mampu menyisihkan jumlah besar sekaligus; menyisihkan sedikit-sedikit tidak akan pernah membuat perbedaan bagi keamanan dan masa depanmu","Menabung berarti menimbun uang sebanyak mungkin tanpa pernah memakainya untuk apa pun, bahkan untuk tujuan penting, sehingga kebahagiaan hidup sehari-hari harus selalu dikorbankan","Menabung bukan tentang berapa banyak yang kamu punya, tapi tentang kebiasaan menyisihkan sebagian secara teratur menuju tujuan yang berarti — yang memberimu keamanan, pilihan, & kendali atas masa depanmu"],answer:2,explain:"Kebiasaan menyisihkan secara teratur menuju tujuan bermakna — pada jumlah berapa pun — adalah inti menabung.",hint:"Apakah menabung tentang jumlahnya, atau tentang kebiasaannya?"},
{n:98,type:"mcq",micro:"Menghubungkan ke keterampilan lain",q:"Menabung & menetapkan tujuan keuangan adalah dasar untuk...",options:["Membuat anggaran, menghindari utang buruk, mengejar peluang (kursus, usaha), & pada akhirnya berinvestasi — semuanya dibangun di atas kebiasaan menyisihkan menuju tujuan","Tidak berhubungan dengan keterampilan keuangan lain apa pun, karena menabung adalah kebiasaan kecil yang berdiri sendiri dan tidak ada kaitannya dengan anggaran, utang, ataupun investasi","Hanya berguna untuk membeli barang yang kamu inginkan, sedangkan membuat anggaran, menghindari utang, dan berinvestasi tidak memerlukan kebiasaan menyisihkan uang sama sekali"],answer:0,explain:"Hampir setiap langkah keuangan berikutnya (anggaran, bebas utang, investasi) berdiri di atas kemampuan menabung secara konsisten.",hint:"Bisakah kamu berinvestasi atau mengejar peluang besar tanpa lebih dulu bisa menabung?"},
{n:99,type:"tf",micro:"Rencana tabungan adalah dokumen hidup",q:"Benar atau Salah: Sebuah rencana tabungan sebaiknya dibuat sekali lalu dipegang tanpa perubahan selamanya, bahkan bila pemasukan, tujuan, harga, & keadaanmu berubah.",answer:false,explain:"Rencana tabungan sebaiknya ditinjau & disesuaikan secara berkala. Rencana yang hidup — diperiksa & diperbarui — jauh lebih berguna daripada rencana beku yang sudah tidak sesuai kenyataan.",hint:"Apakah rencana yang dibuat setahun lalu masih cocok dengan keadaanmu sekarang?"},
{n:100,type:"open",micro:"Kapstone: panduan 'Menabung untuk Tujuan' untuk teman sebaya",q:"Tulis panduan singkat (8–10 poin) berjudul 'Menabung untuk Tujuan: Cara Mulai' untuk teman sebayamu. Cakup: apa & mengapa menabung, menetapkan tujuan yang jelas (jumlah + tenggat + langkah), bayar diri sendiri dulu, dana darurat, wadah terpisah & tempat aman, melacak & merayakan kemajuan, menjadikan rutin/otomatis, menghadapi godaan memakainya, mulai kecil & sedini mungkin, & menyeimbangkan dengan menikmati sebagian. Gunakan bahasa jelas & contoh konkret.",explain:"Panduan baik menyederhanakan semua prinsip: definisi & guna, tujuan SMART sederhana, hitung langkah, bayar diri sendiri dulu, dana darurat, wadah terpisah & aman, lacak & rayakan, hadapi godaan, mulai kecil & dini, & seimbang — dengan contoh angka konkret & bahasa ramah sebaya.",hint:"Tiap poin harus bisa langsung dipakai teman sebayamu minggu ini saat menerima uang saku.",sample:"Contoh panduan: 1) Menabung = menyisihkan sebagian uang sekarang untuk dipakai nanti. Gunanya: bisa beli hal besar tanpa berutang, & siap kalau ada kejutan (tas rusak, sakit). 2) Pilih SATU tujuan yang jelas: apa persisnya, harganya berapa, & kapan kamu mau punya. Contoh: 'sepatu Rp280.000 dalam 10 minggu.' 3) Hitung langkahnya: harga ÷ jumlah minggu = berapa per minggu. Rp280.000 ÷ 10 = Rp28.000/minggu. 4) BAYAR DIRI SENDIRI DULU: begitu terima uang saku, langsung sisihkan tabungan SEBELUM jajan apa pun. Jangan menabung 'dari sisa' — biasanya tidak ada sisa. 5) Buat dana darurat kecil dulu (mis. Rp100.000) sebelum tujuan lain, supaya kejutan tidak jadi krisis. 6) Simpan di wadah terpisah yang agak sulit dijangkau — amplop berlabel yang dipegang orang tua, atau rekening tanpa kartu. Jangan campur dengan uang jajan. 7) Catat tiap setoran & totalnya (di buku atau ponsel). Lihat kemajuannya tiap minggu — 'sudah Rp200.000, tinggal Rp80.000!' 8) Kalau tergoda memakainya: berhenti, ingat berapa lama kamu menabung & untuk apa, tunggu 2 hari. Godaan sering hilang. 9) Mulai KECIL & SEKARANG. Rp5.000/minggu jadi Rp260.000 setahun. Menunggu 'nanti kalau uangku banyak' sering tidak pernah datang. 10) Sisakan sedikit untuk kesenangan (mis. Rp10.000/minggu) supaya kamu tidak jenuh & berhenti total. Rayakan saat tujuan tercapai, lalu tetapkan tujuan baru."},
];
